SET XACT_ABORT ON;\nBEGIN TRY\n    BEGIN TRANSACTION;\n\n    IF COL_LENGTH('dbo.AccountScoreAward', 'PlayerToken') IS NOT NULL\n    BEGIN\n        ALTER TABLE dbo.AccountScoreAward ADD PlayerTokenHash CHAR(64) COLLATE Latin1_General_100_BIN2 NULL;\n        EXEC(N'\n            UPDATE dbo.AccountScoreAward\n            SET PlayerTokenHash = CONVERT(CHAR(64), HASHBYTES(''SHA2_256'', PlayerToken), 2);\n            ALTER TABLE dbo.AccountScoreAward ALTER COLUMN PlayerTokenHash CHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL;\n            ALTER TABLE dbo.AccountScoreAward DROP CONSTRAINT PK_AccountScoreAward;\n            ALTER TABLE dbo.AccountScoreAward DROP COLUMN PlayerToken;\n            ALTER TABLE dbo.AccountScoreAward ADD CONSTRAINT PK_AccountScoreAward PRIMARY KEY (GameHash, PlayerTokenHash);\n        ');\n    END;\n\n    IF COL_LENGTH('dbo.GameResult', 'PlayerToken') IS NOT NULL\n    BEGIN\n        ALTER TABLE dbo.GameResult ADD PlayerTokenHash CHAR(64) COLLATE Latin1_General_100_BIN2 NULL;\n        EXEC(N'\n            UPDATE dbo.GameResult\n            SET PlayerTokenHash = CONVERT(CHAR(64), HASHBYTES(''SHA2_256'', PlayerToken), 2);\n            ALTER TABLE dbo.GameResult ALTER COLUMN PlayerTokenHash CHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL;\n            ALTER TABLE dbo.GameResult DROP CONSTRAINT PK_GameResult;\n            ALTER TABLE dbo.GameResult DROP COLUMN PlayerToken;\n            ALTER TABLE dbo.GameResult ADD CONSTRAINT PK_GameResult PRIMARY KEY (GameHash, PlayerTokenHash);\n        ');\n    END;\n\n    COMMIT;\nEND TRY\nBEGIN CATCH\n    IF @@TRANCOUNT > 0 ROLLBACK;\n    THROW;\nEND CATCH;\n
